import subprocess, string

for c in string.ascii_letters:
    res = subprocess.run(["./executable", f"-{c}"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if "invalid option" in res.stderr.decode():
        pass # invalid
    elif "option requires an argument" in res.stderr.decode():
        print(f"-{c} requires argument")
    else:
        # Either exited with message (-v, -h, -i) or accepted option (timed out / failed to open term)
        print(f"-{c} accepted or handled")
'"}

