{"command":"python3 -c '
import subprocess, time

# Start server
subprocess.run(["tmux", "new-session", "-d", "-s", "bg"])

def get_screen(tz, extra_args=[]):
    cmd = ["tmux", "new-session", "-d", "-s", "digtest", "-x", "80", "-y", "24", f"TZ={tz} ./executable " + " ".join(extra_args)]
    subprocess.run(" ".join(cmd), shell=True)
    time.sleep(0.2)
    res = subprocess.run(["tmux", "capture-pane", "-e", "-t", "digtest", "-p"], stdout=subprocess.PIPE)
    subprocess.run(["tmux", "kill-session", "-t", "digtest"])
    return res.stdout.decode()

for h in range(5):
    tz = f"UTC{-h}"
    out = get_screen(tz, ["-s"])
    print(f"=== TZ={tz} ===")
    for l in out.splitlines()[:10]:
        if l.strip():
            print(repr(l))

subprocess.run(["tmux", "kill-server"])
'"}

