{"command":"python3 -c '
import subprocess, time, re

def get_screen_info(tz):
    cmd = ["tmux", "new-session", "-d", "-s", "digtest", "-x", "80", "-y", "24", "-e", f"TZ={tz}", "./executable", "-s", "-f", "%H%M%S"]
    subprocess.run(cmd)
    time.sleep(0.15)
    res = subprocess.run(["tmux", "capture-pane", "-e", "-t", "digtest", "-p"], stdout=subprocess.PIPE)
    res_plain = subprocess.run(["tmux", "capture-pane", "-t", "digtest", "-p"], stdout=subprocess.PIPE)
    subprocess.run(["tmux", "kill-session", "-t", "digtest"])

    raw = res.stdout.decode()
    plain = res_plain.stdout.decode()

    time_str = None
    for line in plain.splitlines():
        line_str = line.strip()
        if len(line_str) == 6 and line_str.isdigit():
            time_str = line_str
            break

    grid = []
    for line in raw.splitlines()[:6]:
        s = ""
        in_color = False
        i = 0
        while i < len(line):
            if line[i:i+5] == "\x1b[42m":
                in_color = True
                i += 5
            elif line[i:i+5] == "\x1b[49m":
                in_color = False
                i += 5
            else:
                m = re.match(r"\x1b\[[0-9;]*[a-zA-Z]", line[i:])
                if m:
                    i += len(m.group(0))
                else:
                    s += "#" if in_color else "."
                    i += 1
        grid.append(s)
    return time_str, grid

digits_found = {}

for h in range(24):
    tz = f"UTC{-h}"
    t_str, g = get_screen_info(tz)
    if not t_str or len(g) < 6:
        continue
    x0 = None
    for c in range(len(g[2])):
        if g[2][c:c+2] == "##" and len(g[2]) > c+17 and g[2][c+17:c+19] == "##":
            x0 = c - 14
            break
    if x0 is None:
        continue

    slices = [
        (0, x0, x0+6),
        (1, x0+7, x0+13),
        (2, x0+17, x0+23),
        (3, x0+24, x0+30),
        (4, x0+34, x0+40),
        (5, x0+41, x0+47)
    ]
    for idx, start, end in slices:
        d_char = t_str[idx]
        if d_char not in digits_found:
            matrix = []
            for r in range(1, 6):
                row_str = g[r][start:end]
                matrix.append(row_str)
            digits_found[d_char] = matrix

for d in sorted(digits_found.keys()):
    print(f"=== DIGIT {d} ===")
    for row in digits_found[d]:
        print(repr(row.replace("#", "X").replace(".", " ")))
'"}

