import subprocess, time, re

def get_screen_raw(tz):
    cmd = ["tmux", "new-session", "-d", "-s", "digextr2", "-x", "80", "-y", "24", "-e", f"TZ={tz}", "./executable", "-s", "-f", "%H%M%S"]
    subprocess.run(cmd)
    time.sleep(0.15)
    res = subprocess.run(["tmux", "capture-pane", "-e", "-t", "digextr2", "-p"], stdout=subprocess.PIPE)
    res_p = subprocess.run(["tmux", "capture-pane", "-t", "digextr2", "-p"], stdout=subprocess.PIPE)
    subprocess.run(["tmux", "kill-session", "-t", "digextr2"])

    plain = res_p.stdout.decode()
    time_str = None
    for l in plain.splitlines():
        if len(l.strip()) == 6 and l.strip().isdigit():
            time_str = l.strip()
            break

    raw = res.stdout.decode()
    clock_lines = [l for l in raw.splitlines() if "\x1b[42m" in l or "\x1b[49m" in l]
    return time_str, clock_lines

digits = {}

for h in range(24):
    tz = f"UTC{-h}"
    t_str, lines = get_screen_raw(tz)
    if not t_str or len(lines) != 5:
        continue

    positions = [5, 12, 22, 29, 39, 46]
    for idx, x_start in enumerate(positions):
        d_char = t_str[idx]
        if d_char not in digits:
            matrix = []
            for r in range(5):
                line = lines[r]
                row_cells = []
                for cell_idx in range(3):
                    col_pos = x_start + cell_idx * 2
                    curr_bg = False
                    curr_col = 0
                    i = 0
                    while i < len(line):
                        if line[i:i+5] == "\x1b[42m":
                            curr_bg = True
                            i += 5
                        elif line[i:i+5] == "\x1b[49m":
                            curr_bg = False
                            i += 5
                        elif line[i] == "\x1b":
                            m = re.match(r"\x1b\[[0-9;]*[a-zA-Z]|\x0e|\x0f", line[i:])
                            if m: i += len(m.group(0))
                            else: i += 1
                        else:
                            if curr_col == col_pos:
                                row_cells.append(1 if curr_bg else 0)
                                break
                            curr_col += 1
                            i += 1
                matrix.append(row_cells)
            digits[d_char] = matrix

for d in sorted(digits.keys()):
    print(f"/* Digit {d} */")
    print("{")
    for row in digits[d]:
        print("    {" + ", ".join(map(str, row)) + "},")
    print("},")
'"}

