typedef struct {
    int x;
    int y;
    int w;
    int h;
    int center;
} geo_t;

typedef struct {
    int show_seconds;
    int screensaver;
    int show_box;
    int color;
    int bold;
    int twelve;
    int utc;
    int rebound;
    int noquit;
    int hide_date;
    int blinking;
    long delay;
    long nsdelay;
    char *format;
    char *tty;
} clock_opts_t;

typedef struct {
    int vx;
    int vy;
} rebound_t;

static geo_t geo;
static clock_opts_t clock_opts;
static rebound_t rebound;

static void print_usage(void) {
    printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n"
           "    -s            Show seconds                                   \n"
           "    -S            Screensaver mode                               \n"
           "    -x            Show box                                       \n"
           "    -c            Set the clock at the center of the terminal    \n"
           "    -C [0-7]      Set the clock color                            \n"
           "    -b            Use bold colors                                \n"
           "    -t            Set the hour in 12h format                     \n"
           "    -u            Use UTC time                                   \n"
           "    -T tty        Display the clock on the specified terminal    \n"
           "    -r            Do rebound the clock                           \n"
           "    -f format     Set the date format                            \n"
           "    -n            Don't quit on keypress                         \n"
           "    -v            Show tty-clock version                         \n"
           "    -i            Show some info about tty-clock                 \n"
           "    -h            Show this page                                 \n"
           "    -D            Hide date                                      \n"
           "    -B            Enable blinking colon                          \n"
           "    -d delay      Set the delay between two redraws of the clock. Default 1s. \n"
           "    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n");
}

static void cleanup_and_exit(int sig) {
    (void)sig;
    endwin();
    exit(0);
}

static void draw_number(int num, int sy, int sx) {
    for (int r = 0; r < 5; r++) {
        for (int c = 0; c < 3; c++) {
            if (number[num][r][c]) {
                attron(A_REVERSE);
                mvaddstr(sy + r, sx + c * 2, "  ");
                attroff(A_REVERSE);
            } else {
                mvaddstr(sy + r, sx + c * 2, "  ");
            }
        }
    }
}

static void draw_colon(int sy, int sx, int show) {
    for (int r = 0; r < 5; r++) {
        if (show && colon[r][0]) {
            attron(A_REVERSE);
            mvaddstr(sy + r, sx, "  ");
            attroff(A_REVERSE);
        } else {
            mvaddstr(sy + r, sx, "  ");
        }
    }
}

int main(int argc, char **argv) {
    geo.x = 1;
    geo.y = 1;
    geo.w = 30;
    geo.h = 5;
    geo.center = 0;

    clock_opts.show_seconds = 0;
    clock_opts.screensaver = 0;
    clock_opts.show_box = 0;
    clock_opts.color = 2;
    clock_opts.bold = 0;
    clock_opts.twelve = 0;
    clock_opts.utc = 0;
    clock_opts.rebound = 0;
    clock_opts.noquit = 0;
    clock_opts.hide_date = 0;
    clock_opts.blinking = 0;
    clock_opts.delay = 1;
    clock_opts.nsdelay = 0;
    clock_opts.format = NULL;
    clock_opts.tty = NULL;

    rebound.vx = 1;
    rebound.vy = 1;

    static const char *optstr = "iuvsScbtrahDBxnC:f:d:a:T:";

    int c;
    while ((c = getopt(argc, argv, optstr)) != -1) {
        switch (c) {
        case 's':
            clock_opts.show_seconds = 1;
            break;
        case 'S':
            clock_opts.screensaver = 1;
            break;
        case 'x':
            clock_opts.show_box = 1;
            break;
        case 'c':
            geo.center = 1;
            break;
        case 'C':
            if (optarg) {
                int val = atoi(optarg);
                if (val >= 0 && val <= 7) {
                    clock_opts.color = val;
                } else {
                    clock_opts.color = val % 8;
                    if (clock_opts.color < 0) clock_opts.color += 8;
                }
