            break;
        case 'd':
            if (optarg) clock_opts.delay = atol(optarg);
            break;
        case 'a':
            if (optarg) clock_opts.nsdelay = atol(optarg);
            break;
        case '?':
        default:
            print_usage();
            exit(0);
        }
    }

    if (clock_opts.tty) {
        struct stat st;
        if (stat(clock_opts.tty, &st) < 0) {
            fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n", clock_opts.tty, strerror(errno));
            exit(1);
        }
        if (!S_ISCHR(st.st_mode)) {
            fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", clock_opts.tty);
            exit(1);
        }
        FILE *f = fopen(clock_opts.tty, "r+");
        if (!f) {
            fprintf(stderr, "tty-clock: error: couldn't open '%s': %s.\n", clock_opts.tty, strerror(errno));
            exit(1);
        }
        SCREEN *term = newterm(NULL, f, f);
        if (!term) {
            fprintf(stderr, "tty-clock: error: couldn't initialize terminal '%s'.\n", clock_opts.tty);
            exit(1);
        }
        set_term(term);
    } else {
        initscr();
    }

    cbreak();
    noecho();
    curs_set(0);
    keypad(stdscr, TRUE);
    nodelay(stdscr, TRUE);

    start_color();
    use_default_colors();
    init_pair(1, clock_opts.color, -1);

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    int blink_state = 1;

    while (1) {
        erase();

        if (clock_opts.bold) {
            attron(COLOR_PAIR(1) | A_BOLD);
        } else {
            attron(COLOR_PAIR(1));
        }

        time_t rawtime = time(NULL);
        struct tm *tm = clock_opts.utc ? gmtime(&rawtime) : localtime(&rawtime);

        int hour = clock_opts.twelve ? (tm->tm_hour % 12 ? tm->tm_hour % 12 : 12) : tm->tm_hour;
        int min = tm->tm_min;
        int sec = tm->tm_sec;

        int h1 = hour / 10;
        int h2 = hour % 10;
        int m1 = min / 10;
        int m2 = min % 10;
        int s1 = sec / 10;
        int s2 = sec % 10;

        geo.w = clock_opts.show_seconds ? 47 : 30;
        geo.h = 5;

        if (geo.center) {
            geo.x = (COLS - geo.w) / 2;
            geo.y = (LINES - geo.h) / 2;
        } else if (clock_opts.rebound) {
            int min_x = 1;
            int max_x = COLS - geo.w;
            int min_y = 1;
            int max_y = LINES - geo.h - (clock_opts.hide_date ? 0 : 2);

            if (clock_opts.show_box) {
                min_x = 1;
                max_x = COLS - geo.w - 1;
                min_y = 1;
                max_y = LINES - geo.h - (clock_opts.hide_date ? 1 : 3);
            }

            if (geo.x <= min_x) {
                geo.x = min_x;
                rebound.vx = 1;
            } else if (geo.x >= max_x) {
                geo.x = max_x;
                rebound.vx = -1;
            }

            if (geo.y <= min_y) {
                geo.y = min_y;
                rebound.vy = 1;
            } else if (geo.y >= max_y) {
                geo.y = max_y;
                rebound.vy = -1;
            }

            geo.x += rebound.vx;
            geo.y += rebound.vy;
        }

        // Draw box if enabled
        if (clock_opts.show_box) {
            int bx = geo.x - 1;
            int by = geo.y - 1;
            int bw = geo.w;

            mvaddch(by, bx, ACS_ULCORNER);
            mvhline(by, bx + 1, ACS_HLINE, bw);
            mvaddch(by, bx + bw + 1, ACS_URCORNER);

            for (int r = 0; r < 5; r++) {
                mvaddch(by + 1 + r, bx, ACS_VLINE);
                mvaddch(by + 1 + r, bx + bw + 1, ACS_VLINE);
            }

            mvaddch(by + 6, bx, ACS_LLCORNER);
            mvhline(by + 6, bx + 1, ACS_HLINE, bw);
            mvaddch(by + 6, bx + bw + 1, ACS_LRCORNER);
        }

        // Draw digits
        int show_colon_now = clock_opts.blinking ? blink_state : 1;
        draw_number(h1, geo.y, geo.x);
        draw_number(h2, geo.y, geo.x + 7);
        draw_colon(geo.y, geo.x + 14, show_colon_now);
        draw_number(m1, geo.y, geo.x + 17);
        draw_number(m2, geo.y, geo.x + 24);

        if (clock_opts.show_seconds) {
            draw_colon(geo.y, geo.x + 31, show_colon_now);
            draw_number(s1, geo.y, geo.x + 34);
            draw_number(s2, geo.y, geo.x + 41);
        }

        // Draw date if not hidden
        if (!clock_opts.hide_date) {
            char date_str[256];
            const char *fmt = clock_opts.format ? clock_opts.format : "%Y-%m-%d";
            strftime(date_str, sizeof(date_str), fmt, tm);
            if (clock_opts.twelve) {
                strncat(date_str, tm->tm_hour >= 12 ? " [PM]" : " [AM]", sizeof(date_str) - strlen(date_str) - 1);
            }

            int date_len = strlen(date_str);
            int date_x = geo.x + (geo.w - date_len) / 2;
            int date_y = geo.y + 6;

            if (clock_opts.show_box) {
                mvaddch(date_y - 1, date_x - 1, ACS_ULCORNER);
                mvhline(date_y - 1, date_x, ACS_HLINE, date_len);
                mvaddch(date_y - 1, date_x + date_len, ACS_URCORNER);

                mvaddch(date_y, date_x - 1, ACS_VLINE);
                mvaddstr(date_y, date_x, date_str);
                mvaddch(date_y, date_x + date_len, ACS_VLINE);

                mvaddch(date_y + 1, date_x - 1, ACS_LLCORNER);
                mvhline(date_y + 1, date_x, ACS_HLINE, date_len);
                mvaddch(date_y + 1, date_x + date_len, ACS_LRCORNER);
            } else {
                mvaddstr(date_y, date_x, date_str);
            }
        }

        refresh();

        int timeout_ms = (int)(clock_opts.delay * 1000 + clock_opts.nsdelay / 1000000);
        if (timeout_ms <= 0) timeout_ms = 10;

        struct pollfd pfd = { .fd = STDIN_FILENO, .events = POLLIN };
        int poll_res = poll(&pfd, 1, timeout_ms);

        if (poll_res > 0 && (pfd.revents & POLLIN)) {
            int ch = wgetch(stdscr);
            if (ch != ERR) {
                if (clock_opts.screensaver) {
                    if (!clock_opts.noquit) {
                        endwin();
                        exit(0);
                    }
                } else {
                    switch (ch) {
                    case 'q':
                    case 'Q':
                        if (!clock_opts.noquit) {
                            endwin();
                            exit(0);
                        }
                        break;
                    case 's':
                    case 'S':
                        clock_opts.show_seconds = !clock_opts.show_seconds;
                        break;
                    case 'x':
                    case 'X':
                        clock_opts.show_box = !clock_opts.show_box;
                        break;
                    case 'c':
                    case 'C':
                        geo.center = !geo.center;
                        break;
                    case 'b':
                    case 'B':
                        clock_opts.bold = !clock_opts.bold;
                        break;
                    case 'r':
                    case 'R':
                        clock_opts.rebound = !clock_opts.rebound;
                        break;
                    case 't':
                    case 'T':
                        clock_opts.twelve = !clock_opts.twelve;
                        break;
                    case '0': case '1': case '2': case '3':
                    case '4': case '5': case '6': case '7':
                        clock_opts.color = ch - '0';
                        init_pair(1, clock_opts.color, -1);
                        break;
                    case 'k':
                    case 'K':
                    case KEY_UP:
                        if (!geo.center) geo.y = (geo.y > 1) ? geo.y - 1 : 1;
                        break;
                    case 'j':
                    case 'J':
                    case KEY_DOWN:
                        if (!geo.center) geo.y++;
                        break;
                    case 'h':
                    case 'H':
                    case KEY_LEFT:
                        if (!geo.center) geo.x = (geo.x > 1) ? geo.x - 1 : 1;
                        break;
                    case 'l':
                    case 'L':
                    case KEY_RIGHT:
                        if (!geo.center) geo.x++;
                        break;
                    }
                }
            }
        }

        if (clock_opts.blinking) {
            blink_state = !blink_state;
        }
    }

    endwin();
    return 0;
}
EOF"}

