static const int colon[5][1] = {
    {0},
    {1},
    {0},
    {1},
    {0}
};

typedef struct {
    int x;
    int y;
    int w;
    int h;
    int center;
} geo_t;

typedef struct {
    int show_seconds;
    int screensaver;
    int show_box;
    int color;
    int bold;
    int twelve;
    int utc;
    int rebound;
    int noquit;
    int hide_date;
    int blinking;
    long delay;
    long nsdelay;
    char *format;
    char *tty;
} clock_opts_t;

typedef struct {
    int vx;
    int vy;
} rebound_t;

static geo_t geo;
static clock_opts_t clock_opts;
static rebound_t rebound;

static void print_usage(void) {
    printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n"
           "    -s            Show seconds                                   \n"
           "    -S            Screensaver mode                               \n"
           "    -x            Show box                                       \n"
           "    -c            Set the clock at the center of the terminal    \n"
           "    -C [0-7]      Set the clock color                            \n"
           "    -b            Use bold colors                                \n"
           "    -t            Set the hour in 12h format                     \n"
           "    -u            Use UTC time                                   \n"
           "    -T tty        Display the clock on the specified terminal    \n"
           "    -r            Do rebound the clock                           \n"
           "    -f format     Set the date format                            \n"
           "    -n            Don't quit on keypress                         \n"
           "    -v            Show tty-clock version                         \n"
           "    -i            Show some info about tty-clock                 \n"
           "    -h            Show this page                                 \n"
           "    -D            Hide date                                      \n"
           "    -B            Enable blinking colon                          \n"
           "    -d delay      Set the delay between two redraws of the clock. Default 1s. \n"
           "    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n");
}

static void cleanup_and_exit(int sig) {
    (void)sig;
    endwin();
    exit(0);
}

static void draw_number(int num, int sy, int sx) {
    for (int r = 0; r < 5; r++) {
        for (int c = 0; c < 3; c++) {
            if (number[num][r][c]) {
                attron(A_REVERSE);
                mvaddstr(sy + r, sx + c * 2, "  ");
                attroff(A_REVERSE);
            } else {
                mvaddstr(sy + r, sx + c * 2, "  ");
            }
        }
    }
}

static void draw_colon(int sy, int sx, int show) {
    for (int r = 0; r < 5; r++) {
        if (show && colon[r][0]) {
            attron(A_REVERSE);
            mvaddstr(sy + r, sx, "  ");
            attroff(A_REVERSE);
        } else {
            mvaddstr(sy + r, sx, "  ");
        }
    }
}

int main(int argc, char **argv) {
    geo.x = 1;
    geo.y = 1;
    geo.w = 30;
    geo.h = 5;
    geo.center = 0;

    clock_opts.show_seconds = 0;
    clock_opts.screensaver = 0;
    clock_opts.show_box = 0;
    clock_opts.color = 2;
    clock_opts.bold = 0;
    clock_opts.twelve = 0;
    clock_opts.utc = 0;
    clock_opts.rebound = 0;
    clock_opts.noquit = 0;
    clock_opts.hide_date = 0;
    clock_opts.blinking = 0;
    clock_opts.delay = 1;
    clock_opts.nsdelay = 0;
    clock_opts.format = NULL;
    clock_opts.tty = NULL;

    rebound.vx = 1;
    rebound.vy = 1;

    static const char *optstr = "iuvsScbtrahDBxnC:f:d:a:T:";

    int c;
    while ((c = getopt(argc, argv, optstr)) != -1) {
        switch (c) {
        case 's':
            clock_opts.show_seconds = 1;
            break;
        case 'S':
            clock_opts.screensaver = 1;
            break;
        case 'x':
            clock_opts.show_box = 1;
            break;
        case 'c':
            geo.center = 1;
            break;
        case 'C':
            if (optarg) {
                int val = atoi(optarg);
                if (val >= 0 && val <= 7) {
                    clock_opts.color = val;
                } else {
                    clock_opts.color = val % 8;
                    if (clock_opts.color < 0) clock_opts.color += 8;
                }
            }
            break;
        case 'b':
            clock_opts.bold = 1;
            break;
        case 't':
            clock_opts.twelve = 1;
            break;
        case 'u':
            clock_opts.utc = 1;
            break;
        case 'T':
            clock_opts.tty = optarg;
            break;
        case 'r':
            clock_opts.rebound = 1;
            break;
        case 'f':
            clock_opts.format = optarg;
            break;
        case 'n':
            clock_opts.noquit = 1;
            break;
        case 'v':
            puts("TTY-Clock 2 © devel version");
            exit(0);
        case 'i':
            puts("TTY-Clock 2 © by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)");
            exit(0);
        case 'h':
            print_usage();
            exit(0);
        case 'D':
            clock_opts.hide_date = 1;
            break;
        case 'B':
            clock_opts.blinking = 1;
            break;
        case 'd':
            if (optarg) clock_opts.delay = atol(optarg);
            break;
        case 'a':
            if (optarg) clock_opts.nsdelay = atol(optarg);
            break;
        case '?':
        default:
            print_usage();
            exit(0);
        }
    }

    if (clock_opts.tty) {
        struct stat st;
        if (stat(clock_opts.tty, &st) < 0) {
            fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n", clock_opts.tty, strerror(errno));
            exit(1);
        }
        if (!S_ISCHR(st.st_mode)) {
            fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", clock_opts.tty);
            exit(1);
        }
        FILE *f = fopen(clock_opts.tty, "r+");
        if (!f) {
            fprintf(stderr, "tty-clock: error: couldn't open '%s': %s.\n", clock_opts.tty, strerror(errno));
            exit(1);
        }
        SCREEN *term = newterm(NULL, f, f);
        if (!term) {
            fprintf(stderr, "tty-clock: error: couldn't initialize terminal '%s'.\n", clock_opts.tty);
            exit(1);
        }
        set_term(term);
    } else {
        initscr();
    }

    cbreak();
    noecho();
    curs_set(0);
    keypad(stdscr, TRUE);
    nodelay(stdscr, TRUE);

    start_color();
    use_default_colors();
    init_pair(1, clock_opts.color, -1);

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    int blink_state = 1;

    while (1) {
        erase();

        if (clock_opts.bold) {
            attron(COLOR_PAIR(1) | A_BOLD);
        } else {
            attron(COLOR_PAIR(1));
        }

        time_t rawtime = time(NULL);
        struct tm *tm = clock_opts.utc ? gmtime(&rawtime) : localtime(&rawtime);

        int hour = clock_opts.twelve ? (tm->tm_hour % 12 ? tm->tm_hour % 12 : 12) : tm->tm_hour;
        int min = tm->tm_min;
        int sec = tm->tm_sec;

        int h1 = hour / 10;
        int h2 = hour % 10;
        int m1 = min / 10;
        int m2 = min % 10;
        int s1 = sec / 10;
        int s2 = sec % 10;

        geo.w = clock_opts.show_seconds ? 47 : 30;
        geo.h = 5;

        if (geo.center) {
            geo.x = (COLS - geo.w) / 2;
            geo.y = (LINES - geo.h) / 2;
        } else if (clock_opts.rebound) {
            int min_x = 1;
            int max_x = COLS - geo.w;
            int min_y = 1;
            int max_y = LINES - geo.h - (clock_opts.hide_date ? 0 : 2);

            if (clock_opts.show_box) {
                min_x = 1;
                max_x = COLS - geo.w - 1;
                min_y = 1;
                max_y = LINES - geo.h - (clock_opts.hide_date ? 1 : 3);
            }

            if (geo.x <= min_x) {
                geo.x = min_x;
                rebound.vx = 1;
            } else if (geo.x >= max_x) {
                geo.x = max_x;
                rebound.vx = -1;
            }

            if (geo.y <= min_y) {
                geo.y = min_y;
                rebound.vy = 1;
            } else if (geo.y >= max_y) {
                geo.y = max_y;
                rebound.vy = -1;
            }

            geo.x += rebound.vx;
            geo.y += rebound.vy;
        }

        // Draw box if enabled
        if (clock_opts.show_box) {
            int bx = geo.x - 1;
            int by = geo.y - 1;
            int bw = geo.w;

            mvaddch(by, bx, ACS_ULCORNER);
            mvhline(by, bx + 1, ACS_HLINE, bw);
            mvaddch(by, bx + bw + 1, ACS_URCORNER);

            for (int r = 0; r < 5; r++) {
                mvaddch(by + 1 + r, bx, ACS_VLINE);
                mvaddch(by + 1 + r, bx + bw + 1, ACS_VLINE);
            }

            mvaddch(by + 6, bx, ACS_LLCORNER);
            mvhline(by + 6, bx + 1, ACS_HLINE, bw);
            mvaddch(by + 6, bx + bw + 1, ACS_LRCORNER);
        }

        // Draw digits
        int show_colon_now = clock_opts.blinking ? blink_state : 1;
        draw_number(h1, geo.y, geo.x);
        draw_number(h2, geo.y, geo.x + 7);
        draw_colon(geo.y, geo.x + 14, show_colon_now);
        draw_number(m1, geo.y, geo.x + 17);
        draw_number(m2, geo.y, geo.x + 24);

        if (clock_opts.show_seconds) {
            draw_colon(geo.y, geo.x + 31, show_colon_now);
            draw_number(s1, geo.y, geo.x + 34);
            draw_number(s2, geo.y, geo.x + 41);
        }

        // Draw date if not hidden
        if (!clock_opts.hide_date) {
            char date_str[256];
            const char *fmt = clock_opts.format ? clock_opts.format : "%Y-%m-%d";
            strftime(date_str, sizeof(date_str), fmt, tm);
            if (clock_opts.twelve) {
                strncat(date_str, tm->tm_hour >= 12 ? " [PM]" : " [AM]", sizeof(date_str) - strlen(date_str) - 1);
            }

            int date_len = strlen(date_str);
            int date_x = geo.x + (geo.w - date_len) / 2;
            int date_y = geo.y + 6;

            if (clock_opts.show_box) {
                mvaddch(date_y - 1, date_x - 1, ACS_ULCORNER);
                mvhline(date_y - 1, date_x, ACS_HLINE, date_len);
                mvaddch(date_y - 1, date_x + date_len, ACS_URCORNER);

                mvaddch(date_y, date_x - 1, ACS_VLINE);
                mvaddstr(date_y, date_x, date_str);
                mvaddch(date_y, date_x + date_len, ACS_VLINE);

                mvaddch(date_y + 1, date_x - 1, ACS_LLCORNER);
                mvhline(date_y + 1, date_x, ACS_HLINE, date_len);
                mvaddch(date_y + 1, date_x + date_len, ACS_LRCORNER);
            } else {
                mvaddstr(date_y, date_x, date_str);
            }
        }

        refresh();

        int timeout_ms = (int)(clock_opts.delay * 1000 + clock_opts.nsdelay / 1000000);
        if (timeout_ms <= 0) timeout_ms = 10;

        struct pollfd pfd = { .fd = STDIN_FILENO, .events = POLLIN };
        int poll_res = poll(&pfd, 1, timeout_ms);

        if (poll_res > 0 && (pfd.revents & POLLIN)) {
            int ch = wgetch(stdscr);
            if (ch != ERR) {
                if (clock_opts.screensaver) {
                    if (!clock_opts.noquit) {
                        endwin();
                        exit(0);
                    }
                } else {
                    switch (ch) {
                    case 'q':
                    case 'Q':
                        if (!clock_opts.noquit) {
                            endwin();
                            exit(0);
                        }
                        break;
                    case 's':
                    case 'S':
                        clock_opts.show_seconds = !clock_opts.show_seconds;
                        break;
                    case 'x':
                    case 'X':
                        clock_opts.show_box = !clock_opts.show_box;
                        break;
                    case 'c':
                    case 'C':
                        geo.center = !geo.center;
                        break;
                    case 'b':
                    case 'B':
                        clock_opts.bold = !clock_opts.bold;
                        break;
                    case 'r':
                    case 'R':
                        clock_opts.rebound = !clock_opts.rebound;
                        break;
                    case 't':
                    case 'T':
                        clock_opts.twelve = !clock_opts.twelve;
                        break;
                    case '0': case '1': case '2': case '3':
                    case '4': case '5': case '6': case '7':
                        clock_opts.color = ch - '0';
                        init_pair(1, clock_opts.color, -1);
                        break;
                    case 'k':
                    case 'K':
                    case KEY_UP:
                        if (!geo.center) geo.y = (geo.y > 1) ? geo.y - 1 : 1;
                        break;
                    case 'j':
                    case 'J':
                    case KEY_DOWN:
                        if (!geo.center) geo.y++;
                        break;
                    case 'h':
                    case 'H':
                    case KEY_LEFT:
                        if (!geo.center) geo.x = (geo.x > 1) ? geo.x - 1 : 1;
                        break;
                    case 'l':
                    case 'L':
                    case KEY_RIGHT:
                        if (!geo.center) geo.x++;
                        break;
                    }
                }
            }
        }

        if (clock_opts.blinking) {
            blink_state = !blink_state;
        }
    }

    endwin();
    return 0;
}
